 fn recover_close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:semio_framework_value_control_contract::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<semio_framework_value_control_contract::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{use semio_framework_value_control_contract::OriginalEffectCallbackMode;let key=self.close_route.ok_or_else(||invalid("tuple close has no original action"))?;if key.1!=2||key.2!=body||!effect.invocation().is_some_and(|i|i.identity()==key.0&&i.mode()==OriginalEffectCallbackMode::Recover){return Err(invalid("tuple close recovery changed action"))}let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=state.cursor.recover_close_into(body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
